Here's a clean, robust implementation using DFS with path tracking:

```python
def find_cycle(graph: dict[str, list[str]]) -> list[str] | None:
    # Collect all nodes to handle target-only nodes and disconnected components
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in all_nodes}
    path = []  # Tracks the current DFS traversal path

    def dfs(u: str):
        color[u] = GRAY
        path.append(u)

        for v in graph.get(u, []):
            if color[v] == GRAY:
                # Back edge found → cycle detected.
                # Extract nodes from the first occurrence of `v` to current end, then close the cycle.
                idx = path.index(v)
                return path[idx:] + [v]
            elif color[v] == WHITE:
                res = dfs(v)
                if res is not None:
                    return res

        path
